```js
function maxOf(...nums) {
  if (nums.length === 0) return null;
  let m = nums[0];
  for (const n of nums) {
    if (n > m) m = n;
  }
  return m;
}
console.log(maxOf(3, 9, 1));
console.log(maxOf());
